import{_ as d,o as a,c as r,a2 as e}from"./chunks/framework.BXzK3EA4.js";const b=JSON.parse('{"title":"징집 잔존과 군 장부","description":"","frontmatter":{},"headers":[],"relativePath":"world/Conscription-Remnants.md","filePath":"world/Conscription-Remnants.md"}'),h={name:"world/Conscription-Remnants.md"};function o(n,t,i,l,s,p){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="징집-잔존과-군-장부" tabindex="-1">징집 잔존과 군 장부 <a class="header-anchor" href="#징집-잔존과-군-장부" aria-label="Permalink to &quot;징집 잔존과 군 장부&quot;">​</a></h1><p>한국은 붕괴 전에도 징병제 국가였다. 2026년 기준 현역·예비군 명부에 올라 본 사람이 성인 남성의 기본값이다. 붕괴 이후 서울에 「군대가 없다」고 쓰면 그 명부가 거짓이 된다. 이 페이지는 그 명부가 쪼개져 <strong>잔존 군사</strong>가 되는 방식이다. 16번째 국가를 새로 만들지 않고, 기존 생활권 위에 장부를 얹는다.</p><p>설계 제안이다. 병력 수는 잠그지 않는다.</p><h2 id="붕괴가-부대를-어떻게-자르는가" tabindex="-1">붕괴가 부대를 어떻게 자르는가 <a class="header-anchor" href="#붕괴가-부대를-어떻게-자르는가" aria-label="Permalink to &quot;붕괴가 부대를 어떻게 자르는가&quot;">​</a></h2><p>대정전 밤에 사단 간판은 남고 배식·탄약·통신이 끊긴다. 남는 것은 세 장부다.</p><table tabindex="0"><thead><tr><th>장부</th><th>들고 있는 사람</th><th>손에 쥐는 것</th><th>정통성</th></tr></thead><tbody><tr><td>동원 명부</td><td>예비군 중대 서기, 동대 인원계</td><td>이름·군번·마지막 소집일</td><td>「아직 국가가 소집할 수 있다」</td></tr><tr><td>무기고 열쇠</td><td>탄약고 당직, 헌병 잔당</td><td>봉인된 제식 소화기·방호구. 모델명은 공개하지 않는다</td><td>「열쇠를 연 자만 제식」</td></tr><tr><td>동원 거부·탈영</td><td>소집 불응, 붕괴 중 이탈</td><td>눈에 띄는 군용 키트 또는 빈손</td><td>「군인 불신」 평판</td></tr></tbody></table><p>제식 소화기는 <a href="/world/Era-Arms-and-Tech-Level.html">이 시대의 기술과 무구</a>의 군용 잔존 층이다. 대합실 상점 물건이 아니다. 떠돌이 시작 장비에 넣지 않는다.</p><p>징집을 마친 사람이 사격을 기억한다는 것과, 탄약이 있다는 것은 별개다. 탄약은 물자점 보급이고 출격 수를 줄인다.</p><h2 id="생활권에-얹는-위치" tabindex="-1">생활권에 얹는 위치 <a class="header-anchor" href="#생활권에-얹는-위치" aria-label="Permalink to &quot;생활권에 얹는 위치&quot;">​</a></h2><p>16국 슬롯을 늘리지 않는다. 군 잔존은 시설 경비와 겹치되, 같은 이름이 아니다.</p><table tabindex="0"><thead><tr><th>잔존</th><th>얹히는 권역</th><th>기존 군사와의 차이</th><th>충돌</th></tr></thead><tbody><tr><td>신정·부평 축 동원잔존</td><td>서남제작동맹 (구로·금천)</td><td>공병대·차단문 전투조는 공장 방호. 동원잔존은 옛 향토 명부와 탄약고</td><td>프리셋 「구로 군벌」은 이 잔존이 명부를 사병화한 이름이다. 제작평의회와 한 몸이 아니다</td></tr><tr><td>용산 주둔 기억</td><td>용산철도후국</td><td>선로 봉쇄대는 열차를 지킨다. 주둔 기억은 옛 기지 울타리·통역·용역 장부</td><td>외국 군 고유명·군복을 재현하지 않는다. <a href="/design/Unofficial-Fan-AU-Notice.html">AU 고지</a></td></tr><tr><td>수방사 잔편</td><td>도성기록청 가장자리</td><td>의전경비는 문서고. 잔편은 비상 소집 도장</td><td>기록청이 병영이 되면 정통성이 무너진다</td></tr><tr><td>북부 향토 회랑</td><td>북산피난연맹·창동차륜방</td><td>산악 정찰·궤도기병은 생활권 민병. 향토 회랑은 동원 명부를 산으로 들고 간 중대</td><td>난민 수용과 소집이 동시에 걸린다</td></tr></tbody></table><p>탈영 소대 프리셋은 서남 동원잔존에서 빠져나온 소대다. 제식 무기가 「좋지만 눈에 띈다」는 서남 장부에 군번이 남아 있기 때문이다.</p><h2 id="누가-총을-드는가" tabindex="-1">누가 총을 드는가 <a class="header-anchor" href="#누가-총을-드는가" aria-label="Permalink to &quot;누가 총을 드는가&quot;">​</a></h2><table tabindex="0"><thead><tr><th>사람</th><th>징집 이력</th><th>무장 접근</th></tr></thead><tbody><tr><td>떠돌이</td><td>있을 수도 있다. 명부가 없으면 제식이 없다</td><td>봉</td></tr><tr><td>전직 순찰</td><td>대개 예비군 명부</td><td>제식 봉·방패. 소화기는 없음</td></tr><tr><td>탈영 소대</td><td>현역 또는 동원 이탈</td><td>제식 소화기·방호구</td></tr><tr><td>역장</td><td>명부에 이름이 있어도 거점 열쇠가 먼저다</td><td>거점이 무기고를 열면 그때</td></tr><tr><td>상인</td><td>이력과 무관하게 전투원이 아님</td><td>카트</td></tr></tbody></table><p>성인 남성을 전부 소총수로 만들지 않는다. 이력이 있는 사람과 열쇠가 있는 사람만 군용 층에 닿는다.</p><h2 id="넣지-말-것" tabindex="-1">넣지 말 것 <a class="header-anchor" href="#넣지-말-것" aria-label="Permalink to &quot;넣지 말 것&quot;">​</a></h2><ul><li>사단 규모로 서울을 재점령하는 단일 「국군」</li><li>활·궁수 병과</li><li>떠돌이 시작 소총</li><li>외국 정규군 문장·군복 재현</li></ul>',17)])])}const m=d(h,[["render",o]]);export{b as __pageData,m as default};
